template:
% 参数由系统自动注入；球体+截面平面α示意图，O球心，O'截面圆心，P小圆上点
% 视觉归一化：最长外接边缩放到6个坐标单位，线宽与虚线样式不缩放
\pgfmathsetmacro{\r}{sqrt(\R^2 - \d^2)} % 截面小圆半径
\pgfmathsetmacro{\xmin}{-\R-0.6}
\pgfmathsetmacro{\xmax}{\R+0.6}
\pgfmathsetmacro{\ymin}{-\R-0.4}
\pgfmathsetmacro{\ymax}{\R+0.6}
\pgfmathsetmacro{\figscale}{6 / max(\xmax-\xmin, \ymax-\ymin)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    \coordinate (O)  at (0, \d);
    \coordinate (Op) at (0, 0);
    \pgfmathsetmacro{\px}{\r*cos(30)};
    \pgfmathsetmacro{\py}{\r*sin(30)*\rxscale};
    \coordinate (P) at (\px, \py);
    % 平面α 绿色平行四边形
    \draw[green, thick] (-2.2,-0.6) -- (2.2,-0.6) -- (2.8,0.4) -- (-1.6,0.4) -- cycle;
    \ifnum\showlabels>0
        \node[green, below left] at (-2.2,-0.6) {$\alpha$};
    \fi
    % 球体外轮廓大圆
    \draw[black, thick] (0,0) circle (\R);
    % 截面小圆（椭圆）
    \draw[green, thick] (Op) ellipse (\r and \r*\rxscale);
    \draw[green, thick, dashed] (Op) arc[start angle=180, end angle=360, x radius=\r, y radius=\r*\rxscale];
    % 球内部被遮挡虚线圆弧
    \draw[gray, thick, dashed] (0,0) arc[start angle=210, end angle=330, x radius=\R, y radius=\R*0.48];
    % 辅助线段 OO', O'P, OP
    \draw[purple, thick, dashed] (O)--(Op);
    \draw[purple, thick, dashed] (Op)--(P);
    \draw[purple, thick, dashed] (O)--(P);
    % 点标记
    \node[circle, fill=black, inner sep=0.5pt] at (O) {};
    \node[circle, fill=black, inner sep=0.5pt] at (Op) {};
    \node[circle, fill=red, inner sep=0.5pt] at (P) {};
    % 文字标签
    \ifnum\showlabels>0
        \node[above] at (O) {$O$};
        \node[right] at (Op) {$O'$};
        \node[left] at (P) {$P$};
    \fi
\end{tikzpicture}
